/* C versions of the 68000 table kernels (host builds). Same algorithms and 16-bit wraparound as
 * kernels68k.s (generated by gen_kernels.py from the benchmark's routines). */
#ifdef KC_PREFIX    /* the Mac build links these as c_* for the kernel self-test */
#define k_tab4 c_tab4
#define k_mvw c_mvw
#define k_mvw40 c_mvw40
#define k_mvw32 c_mvw32
#define k_exp5 c_exp5
#define k_shrmax c_shrmax
#define k_headk c_headk
#define k_tab5 c_tab5
#define k_mvb5 c_mvb5
#define k_pairs c_pairs
#define k_ptab c_ptab
#define k_wsum c_wsum
#define k_maxabs16 c_maxabs16
#define k_maxabs32 c_maxabs32
#define k_apply16 c_apply16
#define k_addres c_addres
#define k_shr32to16 c_shr32to16
#define k_normpass c_normpass
#define k_ffnact c_ffnact
#define k_apply16c c_apply16c
#define k_dot8 c_dot8
#define k_scores c_scores
#define k_softp c_softp
#define k_softw c_softw
#define k_rshr c_rshr
#define k_huff2 c_huff2
#define k_exp40 c_exp40
#define k_expg c_expg
#define k_fletcher c_fletcher
#endif
#include "engine.h"

static void bld(const int16_t *x, int k, int16_t *out, long stride)
{
    uint16_t c[5], S = (uint16_t)x[0], val;
    int j, idx, n = k == 4 ? 81 : 243;
    c[0] = (uint16_t)x[0];
    for (j = 1; j < k; j++) { c[j] = (uint16_t)(x[j] - 2 * S); S = (uint16_t)(S + x[j]); }
    val = (uint16_t)-S;
    for (idx = 0; idx < n; idx++) {
        int t = idx;
        out[idx * stride] = (int16_t)val;
        for (j = 0; t % 3 == 2; j++) t /= 3;
        val = (uint16_t)(val + c[j < k ? j : 0]);
    }
}

void k_tab4(const int16_t *x, long groups, int16_t *lut)   /* group-contiguous: entry g*81 + idx */
{
    long g;
    for (g = 0; g < groups; g++) bld(x + 4 * g, 4, lut + 81 * g, 1);
}

void k_mvw40(const int16_t *codes, const int16_t *lutmid, long nout, int16_t *out)
{
    k_mvw(codes, lutmid, nout, 40, out);
}

void k_tab5(const int16_t *x, long groups, int16_t *lut)
{
    long g;
    for (g = 0; g < groups; g++) bld(x + 5 * g, 5, lut + 243 * g, 1);
}

void k_mvw(const int16_t *codes, const int16_t *lutmid, long nout, long n, int16_t *out)
{
    long i, j;
    for (i = 0; i < nout; i++) {
        uint16_t d1 = 0;
        for (j = 0; j < n; j++) d1 = (uint16_t)(d1 + lutmid[*codes++ >> 1]);
        out[i] = (int16_t)d1;
    }
}

void k_mvb5(const uint8_t *codes, const int16_t *lut, long nout, long n, int16_t *out)
{
    long i, j;
    for (i = 0; i < nout; i++) {
        uint16_t d1 = 0;
        for (j = 0; j < n; j++) d1 = (uint16_t)(d1 + lut[j * 243 + *codes++]);
        out[i] = (int16_t)d1;
    }
}

void k_pairs(const int16_t *h, long npairs, int16_t *lut)
{
    long p;
    int row, col;
    for (p = 0; p < npairs; p++) {
        uint16_t h1 = (uint16_t)h[2 * p], h2 = (uint16_t)h[2 * p + 1];
        uint16_t d0 = (uint16_t)-(uint16_t)((uint16_t)(h1 + h2) << 3);
        uint16_t d4 = (uint16_t)(h1 - (uint16_t)((uint16_t)(h2 << 4) - h2));
        for (row = 0; row < 16; row++)
            for (col = 0; col < 16; col++) {
                *lut++ = (int16_t)d0;
                d0 = (uint16_t)(d0 + (col < 15 ? h2 : d4));
            }
    }
}

void k_ptab(const int16_t *u, long n, int16_t *ptab)
{
    long t;
    int i;
    for (t = 0; t < n; t++) {
        uint16_t d3 = (uint16_t)-(uint16_t)((uint16_t)u[t] << 3);
        for (i = 0; i < 16; i++) { *ptab++ = (int16_t)d3; d3 = (uint16_t)(d3 + u[t]); }
    }
}

void k_wsum(const uint8_t *vb, const int16_t *ptab, long ctx, int16_t *out)
{
    int d;
    long t;
    for (d = 0; d < 40; d++) {
        uint16_t a = 0;
        for (t = 0; t < ctx; t++) a = (uint16_t)(a + ptab[t * 16 + vb[t * 40 + d] / 2]);
        out[d] = (int16_t)a;
    }
}

/* ---- scalar loops (the 68000 versions are in kernels68k.s; same results) */
unsigned long k_maxabs16(const int16_t *x, long n)
{
    unsigned long m = 0;
    while (n-- > 0) {
        long v = *x++;
        if (v < 0) v = -v;
        if ((unsigned long)v > m) m = (unsigned long)v;
    }
    return m;
}

unsigned long k_maxabs32(const int32_t *x, long n)
{
    uint32_t m = 0;
    while (n-- > 0) {
        int32_t v = *x++;
        uint32_t a = v < 0 ? (uint32_t)0 - (uint32_t)v : (uint32_t)v;
        if (a > m) m = a;
    }
    return m;
}

void k_apply16(const int16_t *x, int16_t *y, long n, long m, long k)
{
    int32_t h = (int32_t)1 << (k - 1);
    while (n-- > 0) *y++ = (int16_t)(((int32_t)*x++ * (int16_t)m + h) >> k);
}

void k_addres(int32_t *r, const int16_t *x, long n, long m, long k)
{
    int32_t h = (int32_t)1 << (k - 1);
    while (n-- > 0) {
        int32_t d = ((int32_t)*x++ * (int16_t)m + h) >> k, a = *r;
        int32_t s = (int32_t)((uint32_t)a + (uint32_t)d);
        if (a >= 0 && d >= 0 && s < 0) s = 2147483647L;
        else if (a < 0 && d < 0 && s >= 0) s = -2147483647L - 1;
        *r++ = s;
    }
}

void k_shr32to16(const int32_t *a, int16_t *b, long n, long s)
{
    while (n-- > 0) *b++ = (int16_t)(*a++ >> s);
}

unsigned long k_normpass(const int32_t *r, const int16_t *g, int16_t *t, int32_t *a, long n, long sh,
                         unsigned long *maxa)
{
    uint32_t ss = 0, mx = 0;
    while (n-- > 0) {
        int32_t v = sh >= 0 ? (*r++ >> sh) : (int32_t)((uint32_t)*r++ << -sh);
        int16_t ti = (int16_t)v;
        int32_t ai = (int32_t)ti * *g++;
        uint32_t aa = ai < 0 ? (uint32_t)-ai : (uint32_t)ai;
        *t++ = ti;
        ss += (uint32_t)((int32_t)ti * ti) >> 8;
        *a++ = ai;
        if (aa > mx) mx = aa;
    }
    *maxa = mx;
    return ss;
}

unsigned long k_ffnact(const int16_t *accg, const int16_t *accu, int32_t *hh, long n, long m, long k,
                       const int16_t *silumid)
{
    int32_t h = (int32_t)1 << (k - 1);
    uint32_t mx = 0;
    while (n-- > 0) {
        int32_t gi = ((int32_t)*accg++ * (int16_t)m + h) >> k, s, v;
        uint32_t a;
        if (gi >= 512) s = gi > 32767 ? 32767 : gi;
        else if (gi < -512) s = 0;
        else s = silumid[gi];
        v = (int32_t)(int16_t)s * *accu++;
        *hh++ = v;
        a = v < 0 ? (uint32_t)-v : (uint32_t)v;
        if (a > mx) mx = a;
    }
    return mx;
}

/* y = clamp((x*m + h) >> k, -q, q) */
void k_apply16c(const int16_t *x, int16_t *y, long n, long m, long k, long q)
{
    int32_t h = (int32_t)1 << (k - 1);
    while (n-- > 0) {
        int32_t v = ((int32_t)*x++ * (int16_t)m + h) >> k;
        *y++ = (int16_t)(v > q ? q : v < -q ? -q : v);
    }
}

long k_dot8(const int8_t *w, const int16_t *y, long n)
{
    int32_t s = 0;
    while (n-- > 0) s += (int32_t)*w++ * *y++;
    return s;
}

/* attention scores in 1/64 nat: z[s] = clamp16(clamp70000(S[s] * (Cq*sk[s])) - bias[(pos - s) & 63]);
 * sk[s] = {m, e} pairs. Returns max z. Same arithmetic as sf_mul + sf_apply in engine.c. */
long k_scores(const int16_t *S, const int16_t *sk, long n, long cqm, long cqe, const int16_t *bias, long pos,
              int16_t *z)
{
    long s, zmax = -32768;
    for (s = 0; s < n; s++) {
        int32_t a = 0, v;
        int16_t m = sk[2 * s], e = sk[2 * s + 1];
        if (cqm && m) {
            uint32_t p = (uint32_t)(uint16_t)cqm * (uint16_t)m;
            int32_t cm, ce, kk;
            if (p & 0x20000000UL) { cm = (int32_t)(p >> 15); ce = cqe + e + 15; }
            else { cm = (int32_t)(p >> 14); ce = cqe + e + 14; }
            kk = -ce;
            if (kk >= 31) a = 0;
            else if (kk <= 0) {      /* S*cm*2^-kk, clamped to +-70000 (never needed in practice) */
                int32_t v = (int32_t)S[s] * (int16_t)cm;
                long sh = -kk;
                while (sh > 0 && v < 70000 && v > -70000) { v *= 2; sh--; }
                a = v > 70000 ? 70000 : v < -70000 ? -70000 : v;
            }
            else {
                a = ((int32_t)S[s] * (int16_t)cm + ((int32_t)1 << (kk - 1))) >> kk;
                if (a > 70000) a = 70000;
                if (a < -70000) a = -70000;
            }
        }
        v = a - bias[(pos - s) & 63];
        if (v > 32767) v = 32767;
        if (v < -32768) v = -32768;
        z[s] = (int16_t)v;
        if (v > zmax) zmax = v;
    }
    return zmax;
}

/* p[s] = exp12[idx(zmax - z[s])], returns sum p */
long k_softp(const int16_t *z, long n, long zmax, const int16_t *exp12, int16_t *p)
{
    int32_t P = 0;
    while (n-- > 0) {
        int32_t d = zmax - *z++;
        int16_t v = exp12[d >= 1022 ? 511 : (d + 1) >> 1];
        *p++ = v;
        P += v;
    }
    return P;
}

/* w[s] = (p[s] * (sv[s].m >> 3)) >> (emax - sv[s].e), 0 if sv zero or shift >= 32; returns sum w */
unsigned long k_softw(const int16_t *p, const int16_t *sv, long n, long emax, uint32_t *w)
{
    uint32_t W = 0;
    while (n-- > 0) {
        int16_t m = sv[0], e = sv[1];
        long k = emax - e;
        uint32_t v = (!m || k >= 32) ? 0 : ((uint32_t)(uint16_t)*p * (uint16_t)(m >> 3)) >> k;
        sv += 2;
        p++;
        *w++ = v;
        W += v;
    }
    return W;
}

/* u = (w + h) >> sh, h = 2^(sh-1) (0 if sh = 0) */
void k_rshr(const uint32_t *w, int16_t *u, long n, long sh)
{
    uint32_t h = sh ? (uint32_t)1 << (sh - 1) : 0;
    while (n-- > 0) *u++ = (int16_t)((*w++ + h) >> sh);
}

/* ---- loader kernels (format v3) */
/* Huffman fast path, left-aligned bit buffer. st = {p, bb, bn} (3 longs): bb holds bn valid bits
 * from bit 31 down. Refill 16 bits when bn <= 16. Stops before a code longer than 10 bits
 * (lentab entry 0). Returns symbols decoded. The stream needs 4 readable bytes of slack. */
typedef struct { const uint8_t *p; uint32_t bb; int32_t bn; } HBits2;
long k_huff2(uint32_t *st0, const uint8_t *lentab, const uint8_t *symtab, uint8_t *out, long n)
{
    HBits2 *st = (HBits2 *)st0;
    const uint8_t *p = st->p;
    uint32_t bb = st->bb;
    int32_t bn = st->bn;
    long i;
    for (i = 0; i < n; i++) {
        uint32_t peek;
        int len;
        if (bn <= 16) {
            uint32_t w = ((uint32_t)p[0] << 8) | p[1];
            p += 2;
            bb |= w << (16 - bn);
            bn += 16;
        }
        peek = bb >> 22;
        len = lentab[peek];
        if (!len) break;
        *out++ = symtab[peek];
        bb <<= len;
        bn -= len;
    }
    st->p = p;
    st->bb = bb;
    st->bn = bn;
    return i;
}

/* s1 += byte, s2 += s1 over n bytes; f = {s1, s2} */
void k_fletcher(const uint8_t *p, long n, uint32_t *f)
{
    uint32_t s1 = f[0], s2 = f[1];
    while (n-- > 0) { s1 += *p++; s2 += s1; }
    f[0] = s1;
    f[1] = s2;
}

/* W4 codes (idx + 81g)*2 - 32768 for rows of 160 trits (32 B5 bytes = 8 blocks of 4 bytes -> 40
 * codes). wt[b*8 + k]: word tables already times 2 with the in-block group offsets 0,162,324,486,648
 * folded in; codes: wt0[b0], wt1[b0]+wt2[b1], wt3[b1]+wt4[b2], wt5[b2]+wt6[b3], wt7[b3], plus gg
 * (-32768 + 810 per block, reset per row). Also the model checksum over the B5 bytes. */
void k_exp40(const uint8_t *src, int16_t *out, long rows, const int16_t *wt, uint32_t *f)
{
    uint32_t s1 = f[0], s2 = f[1];
    while (rows-- > 0) {
        int16_t gg = -32768;
        int blk;
        for (blk = 0; blk < 8; blk++, src += 4, gg = (int16_t)(gg + 810)) {
            const int16_t *t0 = wt + src[0] * 8, *t1 = wt + src[1] * 8, *t2 = wt + src[2] * 8, *t3 = wt + src[3] * 8;
            s1 += src[0]; s2 += s1; s1 += src[1]; s2 += s1; s1 += src[2]; s2 += s1; s1 += src[3]; s2 += s1;
            *out++ = (int16_t)(t0[0] + gg);
            *out++ = (int16_t)(t0[1] + t1[2] + gg);
            *out++ = (int16_t)(t1[3] + t2[4] + gg);
            *out++ = (int16_t)(t2[5] + t3[6] + gg);
            *out++ = (int16_t)(t3[7] + gg);
        }
    }
    f[0] = s1;
    f[1] = s2;
}

/* general G (the 512-input down projection, G = 128): word tables times 2 without offsets,
 * gg = -32768 + 162*g counted per code and reset every G codes. Checksum as above. */
void k_expg(const uint8_t *src, int16_t *out, long blocks, long G, const int16_t *wt, uint32_t *f)
{
    uint32_t s1 = f[0], s2 = f[1];
    int16_t gg = -32768;
    long left = G;
#define EMITG(v) do { *out++ = (int16_t)((v) + gg); gg = (int16_t)(gg + 162); \
                      if (--left == 0) { left = G; gg = -32768; } } while (0)
    while (blocks-- > 0) {
        const int16_t *t0 = wt + src[0] * 8, *t1 = wt + src[1] * 8, *t2 = wt + src[2] * 8, *t3 = wt + src[3] * 8;
        s1 += src[0]; s2 += s1; s1 += src[1]; s2 += s1; s1 += src[2]; s2 += s1; s1 += src[3]; s2 += s1;
        src += 4;
        EMITG(t0[0]);
        EMITG(t0[1] + t1[2]);
        EMITG(t1[3] + t2[4]);
        EMITG(t2[5] + t3[6]);
        EMITG(t3[7]);
    }
#undef EMITG
    f[0] = s1;
    f[1] = s2;
}

/* b = (int16)(a >> s), returns max |b| (as 0..32768) */
unsigned long k_shrmax(const int32_t *a, int16_t *b, long n, long s)
{
    unsigned long m = 0;
    while (n-- > 0) {
        int16_t v = (int16_t)(*a++ >> s);
        long x = v < 0 ? -(long)v : v;
        *b++ = v;
        if ((unsigned long)x > m) m = (unsigned long)x;
    }
    return m;
}

/* vocabulary logits: K[v] = ((t[2v] + t[2v+1]) >> 1) * m[v] */
void k_headk(const int16_t *t, const int16_t *m, int32_t *K, long n)
{
    while (n-- > 0) {
        int32_t lg = (int32_t)t[0] + t[1];
        t += 2;
        *K++ = (int32_t)(int16_t)(lg >> 1) * *m++;
    }
}

void k_mvw32(const int16_t *codes, const int16_t *lutmid, long nout, int16_t *out)
{
    k_mvw(codes, lutmid, nout, 32, out);
}

/* W5 codes (idx + 243g)*2 - 32768 for rows of 160 inputs (32 B5 bytes; idx = the byte) + checksum */
void k_exp5(const uint8_t *src, int16_t *out, long rows, uint32_t *f)
{
    uint32_t s1 = f[0], s2 = f[1];
    while (rows-- > 0) {
        int16_t gg = -32768;
        int gi;
        for (gi = 0; gi < 32; gi++, gg = (int16_t)(gg + 486)) {
            s1 += *src;
            s2 += s1;
            *out++ = (int16_t)(*src++ * 2 + gg);
        }
    }
    f[0] = s1;
    f[1] = s2;
}
